import{_ as l,o as n,c as r,j as e,a}from"./chunks/framework.CAXxHpAX.js";const f=JSON.parse('{"title":"金刚经1分-不执形式","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经1分-不执形式.md","filePath":"60-原文段落/金刚经1分-不执形式.md","lastUpdated":null}'),o={name:"60-原文段落/金刚经1分-不执形式.md"};function s(_,t,c,d,p,u){return n(),r("div",null,[...t[0]||(t[0]=[e("h1",{id:"金刚经1分-不执形式",tabindex:"-1"},[a("金刚经1分-不执形式 "),e("a",{class:"header-anchor",href:"#金刚经1分-不执形式","aria-label":'Permalink to "金刚经1分-不执形式"'},"​")],-1),e("blockquote",null,[e("p",null,[a("来源："),e("a",{href:"/01-Raw-Sources/1了空居士讲《金刚经》-第一分法会因由分20160909"},"1了空居士讲《金刚经》-第一分法会因由分20160909"),a(" 切分日期：2026-05-06")])],-1),e("hr",null,null,-1),e("p",null,[e("strong",null,"原文：")],-1),e("p",null,'其实释迦牟尼佛他是"人天师范"，他给我们讲经，他是智慧的流露。我们后世法师讲经，我们都是按照释迦牟尼佛所讲来讲。也就是释迦牟尼佛是我们的本师，我们是"乘佛威神"，所以我们要有这种恭敬。那么你说:了空居士，那你今天有没有搞一个什么袈裟啊？我们俗家人是没有袈裟的，我们只是以真诚恭敬的心来讲，我就没有特别的什么装束了，这个就没有，哈哈。出家人他尤其是在大场合，他们一定要有这种衣冠很整齐的，穿上袈裟去讲的，都是需要这样。但是释迦牟尼佛本身，他是从这个清净心流露出来的这种圆满智慧，所以他自己就不用说:我来穿上袈裟来给大家讲。不要说须菩提一提问，释迦牟尼佛赶快跑过去穿上袈裟，然后来讲,就没有这种执着了。',-1),e("p",null,"我们回头再来说一个现象。我们读《六祖坛经》的时候，六祖升座说法的时候也没有说到六祖去赶快穿个袈裟什么，穿戴整齐出来说法,也没有说这个事情，好像没有说这个事情。包括这个赵州禅师等等，很多人去请教他的时候，他就很自然地坐在那里给大家讲，因为他不是讲经，他是说法。他是自己大彻大悟之后，圆满智慧的流露，所以就没有讲经这种仪礼仪轨了，是这个意思。",-1)])])}const m=l(o,[["render",s]]);export{f as __pageData,m as default};
